const input = $input.first();
let text = '';
if (typeof input.json === 'string') text = input.json;
else if (input.json.data) text = input.json.data;
else if (input.binary) text = Buffer.from(input.binary.data.data, 'base64').toString('utf-8');

const lines = text.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.trim());

const result = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim()) continue;
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let char of line) {
    if (char === '"') inQuotes = !inQuotes;
    else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else current += char;
  }
  values.push(current.trim());
  const obj = {};
  headers.forEach((h, idx) => obj[h] = values[idx] || '');
  result.push({ json: obj });
}
return result;

const input = $input.first();
let text = '';
if (typeof input.json === 'string') text = input.json;
else if (input.json.data) text = input.json.data;
else if (input.binary) text = Buffer.from(input.binary.data.data, 'base64').toString('utf-8');

const lines = text.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.trim());

const result = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim()) continue;
  const values = [];
  let current = '';
  let inQuotes = false;
  for (let char of line) {
    if (char === '"') inQuotes = !inQuotes;
    else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else current += char;
  }
  values.push(current.trim());
  const obj = {};
  headers.forEach((h, idx) => obj[h] = values[idx] || '');
  result.push({ json: obj });
}
return result;

const newsByDate = {};
for (const item of $input.all()) {
  let d = item.json.date || (item.json.datetime ? item.json.datetime.split(' ')[0] : '');
  if (!d) continue;
  if (!newsByDate[d]) newsByDate[d] = [];
  newsByDate[d].push(item.json.title);
}
return [{ json: { newsByDate } }];

const allItems = $input.all();
let newsLookup = {};
const marketData = [];

for (const item of allItems) {
  if (item.json.newsByDate) newsLookup = item.json.newsByDate;
  else if (item.json.date) marketData.push(item);
}

marketData.sort((a, b) => new Date(a.json.date) - new Date(b.json.date));

const merged = [];
for (const item of marketData) {
  let d = item.json.date.split(' ')[0];
  const news = newsLookup[d] || [];
  const newsText = news.length > 0 ? news.slice(0, 3).join(' | ') : "Market is quiet today.";

  merged.push({
    json: {
      ...item.json,
      news_text: newsText,
      news_count: news.length
    }
  });
}

return merged;

// Simple Batch Preparation
const allItems = $input.all();
const inputsArray = allItems.map(item => item.json.news_text);

// We store original items to merge later
return [{
  json: {
    batch_inputs: inputsArray,
    original_items: allItems.map(i => i.json)
  }
}];

// === Strategy Core (Portfolio + Risk Metrics) ===

const rootItem = $input.first();

// --- 1. Load Input Data ---
const hfPayload = rootItem.json.data || rootItem.json;
const sourceNode = $("4. Prepare Batch1").first();
const priceRows = sourceNode.json.original_items;

if (!priceRows) throw new Error("original_items not found");

// --- 2. Normalize Sentiment Output ---
let sentimentList = hfPayload;
if (!Array.isArray(hfPayload)) {
  sentimentList = [hfPayload];
}

// --- 3. Portfolio Initialization ---
const assetList = [...new Set(priceRows.map(r => r.ticker))];
const capitalUnit = 10000 / assetList.length;

const ledger = {};

assetList.forEach(asset => {
  ledger[asset] = {
    freeCash: capitalUnit,
    positionSize: 0,
    hasPosition: false,
    avgEntry: 0,
    mtmValue: capitalUnit
  };
});

// --- 4. Main Backtest Loop ---
const executionLog = [];

let closedTrades = 0;
let profitableTrades = 0;
let sumProfit = 0;
let sumLoss = 0;

const steps = Math.min(priceRows.length, sentimentList.length);

for (let k = 0; k < steps; k++) {

  const row = priceRows[k];
  const sentimentBlock = sentimentList[k];

  const asset = row.ticker;
  const marketPrice = Number.parseFloat(row.price || row.close);

  const account = ledger[asset];
  if (!account) continue;

  // --- Sentiment Evaluation ---
  let dominantSignal = { score: 0, label: "NEUTRAL" };

  if (Array.isArray(sentimentBlock)) {
    dominantSignal = sentimentBlock.reduce((x, y) =>
      y.score > x.score ? y : x, { score: 0 }
    );
  } else if (sentimentBlock?.label) {
    dominantSignal = sentimentBlock;
  }

  const label = dominantSignal.label || "NEUTRAL";
  const score = dominantSignal.score || 0;

  // --- Indicator Handling ---
  const rsiRaw = Number.parseFloat(row.rsi);
  const bbRaw = Number.parseFloat(row.bb_position);
  const macdRaw = Number.parseFloat(row.macd_hist);

  const rsiVal = Number.isFinite(rsiRaw) ? rsiRaw : 50;
  const bbVal = Number.isFinite(bbRaw) ? bbRaw : 0.5;
  const macdVal = Number.isFinite(macdRaw) ? macdRaw : 0;

  // --- Strategy Conditions ---
  const bullish = label === "POSITIVE" && score > 0.7;
  const bearish = label === "NEGATIVE" && score > 0.7;

  const rsiOversold = rsiVal < 40;
  const rsiOverbought = rsiVal > 60;

  const bbLower = bbVal < 0.3;
  const bbUpper = bbVal > 0.7;

  const enterLong =
    bullish ||
    (rsiOversold && macdVal > -5) ||
    bbLower;

  const exitLong =
    bearish ||
    rsiOverbought ||
    bbUpper;

  const signal = enterLong ? "buy" : "sell";

  const note = signal === "buy"
    ? `BUY|S:${score.toFixed(2)} R:${rsiVal.toFixed(1)} B:${bbVal.toFixed(2)} M:${macdVal.toFixed(2)}`
    : `SELL|S:${score.toFixed(2)} R:${rsiVal.toFixed(1)} B:${bbVal.toFixed(2)} M:${macdVal.toFixed(2)}`;

  // --- Execution Engine ---
  let realized = 0;
  let order = "none";

  if (signal === "buy" && !account.hasPosition) {
    account.avgEntry = marketPrice;
    account.positionSize = account.freeCash / marketPrice;
    account.freeCash = 0;
    account.hasPosition = true;
    order = "buy";

  } else if (signal === "sell" && account.hasPosition) {

    const liquidation = account.positionSize * marketPrice;
    realized = liquidation - (account.positionSize * account.avgEntry);

    if (realized > 0) {
      profitableTrades++;
      sumProfit += realized;
    } else {
      sumLoss += Math.abs(realized);
    }

    account.freeCash = liquidation;
    account.positionSize = 0;
    account.hasPosition = false;
    closedTrades++;
    order = "sell";
  }

  const equityNow = account.hasPosition
    ? account.positionSize * marketPrice
    : account.freeCash;

  account.mtmValue = equityNow;

  executionLog.push({
    date: row.date,
    asset,
    price: marketPrice,
    signal,
    order,
    pnl: realized !== 0 ? realized.toFixed(2) : "",
    equity: equityNow.toFixed(2),
    sentiment: label,
    score: score.toFixed(2),
    rsi: rsiVal,
    comment: note
  });
}

// --- 5. Equity Curve ---
const equityByDay = {};
const dayIndex = [...new Set(executionLog.map(e => e.date))].sort();

executionLog.forEach(e => {
  if (!equityByDay[e.date]) equityByDay[e.date] = 0;
  equityByDay[e.date] += Number.parseFloat(e.equity);
});

const curve = dayIndex.map(d => equityByDay[d]);

// --- 6. Risk Metrics ---
let highWatermark = -Infinity;
let drawdownMax = 0;
const returnsArr = [];

for (const value of curve) {
  if (value > highWatermark) highWatermark = value;
  const dd = (highWatermark - value) / highWatermark;
  if (dd > drawdownMax) drawdownMax = dd;
}

for (let i = 1; i < curve.length; i++) {
  const ret = curve[i - 1] !== 0
    ? (curve[i] - curve[i - 1]) / curve[i - 1]
    : 0;
  returnsArr.push(ret);
}

const meanReturn =
  returnsArr.reduce((a, b) => a + b, 0) / returnsArr.length || 0;

const varReturn =
  returnsArr.reduce((a, b) =>
    a + Math.pow(b - meanReturn, 2), 0
  ) / returnsArr.length || 0;

const vol = Math.sqrt(varReturn);
const sharpe =
  vol !== 0 ? (meanReturn / vol) * Math.sqrt(365) : 0;

// --- Final Stats ---
const endingEquity = curve[curve.length - 1] || 10000;
const performance = ((endingEquity - 10000) / 10000) * 100;
const winRatio = closedTrades > 0
  ? (profitableTrades / closedTrades) * 100
  : 0;

const pfRatio =
  sumLoss > 0
    ? sumProfit / sumLoss
    : (sumProfit > 0 ? 999 : 0);

return [{
  json: {
    summary: {
      trades: closedTrades,
      win_rate: winRatio.toFixed(2) + "%",
      profit_factor: pfRatio.toFixed(2),
      total_return: performance.toFixed(2) + "%",
      sharpe_ratio: sharpe.toFixed(2),
      max_drawdown: "-" + (drawdownMax * 100).toFixed(2) + "%",
      final_balance: "$" + endingEquity.toFixed(2)
    },
    log: executionLog
  }
}];

const input = $input.first();

const trades = input.json.log;
const summary = input.json.summary;

if (!trades) throw new Error("No trade data");

const header = 'date,asset,price,signal,order,rsi,sentiment,comment\n';

const csvRows = trades.map(t => {
  const safeComment = (t.comment || '').replace(/"/g, "'");
  return `${t.date},${t.asset},${t.price},${t.signal},${t.order},${t.rsi},${t.sentiment},"${safeComment}"`;
}).join('\n');

const csvContent = header + csvRows;

return [{
  json: {
    summary: summary,
    message: "CSV Ready"
  },
  binary: {
    data: {
      data: Buffer.from(csvContent).toString('base64'),
      mimeType: 'text/csv',
      fileName: 'final_results.csv'
    }
  }
}];
